package com.bank.sharedlib;

import java.util.List;

// Per-service config, equivalent to a small bank-ci.yaml in each repo.
public class ServiceConfig {
    private final String service;
    private final int javaVersion;
    private final List<String> deployTargets; // e.g. [dev, qa, prod]

    public ServiceConfig(String service, int javaVersion, List<String> deployTargets) {
        this.service = service;
        this.javaVersion = javaVersion;
        this.deployTargets = deployTargets;
    }
    public String getService()        { return service; }
    public int getJavaVersion()       { return javaVersion; }
    public List<String> getTargets()  { return deployTargets; }
}
