package com.bank.sharedlib;

import java.util.Map;

// Centralised branch -> environment mapping owned by the library.
public class EnvironmentRouter {
    private static final Map<String, String> BRANCH_TO_ENV = Map.of(
            "dev",  "dev-ns",
            "qa",   "qa-ns",
            "main", "prod-ns");

    public String environmentFor(String branch) {
        String env = BRANCH_TO_ENV.get(branch);
        if (env == null) {
            throw new IllegalArgumentException("Branch '" + branch + "' maps to no environment");
        }
        return env;
    }

    public boolean isProduction(String env) {
        return "prod-ns".equals(env);
    }
}
