package com.bank.sharedlib;

import java.util.Set;

// Prod approval gate, defined ONCE in the library so no service can skip it.
public class ApprovalGate {
    private final Set<String> releaseManagers;
    public ApprovalGate(Set<String> releaseManagers) { this.releaseManagers = releaseManagers; }

    public boolean approve(String approver) {
        return approver != null && releaseManagers.contains(approver);
    }
}
