package com.bank.sharedlib;

import java.util.logging.Logger;

// The reusable template step: ONE implementation for ALL services.
public class BankPipelineTemplate {
    private static final Logger log = Logger.getLogger(BankPipelineTemplate.class.getName());
    private final EnvironmentRouter router;
    private final ApprovalGate gate;

    public BankPipelineTemplate(EnvironmentRouter router, ApprovalGate gate) {
        this.router = router;
        this.gate = gate;
    }

    // Equivalent to calling bankPipeline(service:..., ...) from a Jenkinsfile.
    public boolean run(ServiceConfig cfg, String branch, String prodApprover) {
        String svc = cfg.getService();
        log.info(() -> "[" + svc + "] build  (Java " + cfg.getJavaVersion() + "): mvn clean package");
        log.info(() -> "[" + svc + "] test   : mvn test -> passed");
        log.info(() -> "[" + svc + "] scan   : trivy + sonar -> clean");
        log.info(() -> "[" + svc + "] package: image registry.bank.local/" + svc + ":" + branch);

        String env = router.environmentFor(branch); // branch -> environment
        if (!cfg.getTargets().contains(env.replace("-ns", ""))) {
            log.warning(() -> "[" + svc + "] " + env + " not an allowed target; skipping deploy");
            return false;
        }

        if (router.isProduction(env)) {
            if (!gate.approve(prodApprover)) {
                log.severe("[" + svc + "] PROD approval DENIED for '" + prodApprover + "'");
                return false;
            }
            log.info(() -> "[" + svc + "] PROD approved by " + prodApprover);
        }
        log.info(() -> "[" + svc + "] deploy : kubectl -n " + env + " set image deploy/" + svc);
        return true;
    }
}
