package com.bank.sharedlib;

import java.util.List;
import java.util.Set;
import java.util.logging.*;

public class SharedLibraryDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new SharedLibLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        EnvironmentRouter router = new EnvironmentRouter();
        ApprovalGate gate = new ApprovalGate(Set.of("priya-release-mgr"));
        BankPipelineTemplate template = new BankPipelineTemplate(router, gate);

        // Two services supply ONLY their own small config.
        ServiceConfig transfer = new ServiceConfig("transfer-service", 21, List.of("dev","qa","prod"));
        ServiceConfig fraud    = new ServiceConfig("fraud-service", 17, List.of("dev","qa","prod"));

        // qa branch -> QA, no approval needed.
        template.run(transfer, "qa", null);

        // main branch -> Prod, unauthorised approver blocked.
        template.run(fraud, "main", "rajesh-dev");

        // main branch -> Prod, authorised approver succeeds.
        template.run(fraud, "main", "priya-release-mgr");
    }
}

// ─── Would be in SharedLibLogFormatter.java in a real project ───
class SharedLibLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
