// ─── File: vars/bankPipeline.groovy (in the shared library) ───
def call(Map cfg) {
  def envFor = [dev: 'dev-ns', qa: 'qa-ns', main: 'prod-ns']
  pipeline {
    agent { label 'k8s' }
    stages {
      stage('Build') { steps { sh "mvn -Djava.version=${cfg.javaVersion} clean package" } }
      stage('Test')  { steps { sh 'mvn test' } }
      stage('Scan')  { steps { sh "trivy image --exit-code 1 --severity HIGH,CRITICAL registry.bank.local/${cfg.service}:${GIT_COMMIT}" } }
      stage('Deploy') {
        steps {
          script {
            def targetEnv = envFor[env.BRANCH_NAME]
            if (targetEnv == 'prod-ns') {
              timeout(time: 30, unit: 'MINUTES') {
                input message: "Deploy ${cfg.service} to PROD?", submitter: 'release-managers'
              }
            }
            sh "kubectl -n ${targetEnv} set image deploy/${cfg.service} ${cfg.service}=registry.bank.local/${cfg.service}:${GIT_COMMIT}"
          }
        }
      }
    }
  }
}
